"""Basic Calculator II — defer '+'/'-' to a stack, apply '*'/'/' immediately.

Every number is pushed with its sign; higher-precedence operators combine with
the value already on top of the stack. Python's // floors, so division truncates
via int(a / b).

Time: O(n)   Space: O(n)
"""


class Solution:
    def calculate(self, s: str) -> int:
        stack, number, operator = [], 0, "+"
        for i, ch in enumerate(s):
            if ch.isdigit():
                number = number * 10 + int(ch)
            if (not ch.isdigit() and ch != " ") or i == len(s) - 1:
                if operator == "+":
                    stack.append(number)
                elif operator == "-":
                    stack.append(-number)
                elif operator == "*":
                    stack.append(stack.pop() * number)
                else:
                    stack.append(int(stack.pop() / number))
                number, operator = 0, ch
        return sum(stack)
